import pytest

from mojibake import detect, fix

CLEAN = [
    'café',
    'naïve',
    'Müller',
    "l'apostrophe d'été",
    'She said “hello” to Zürich — wasn’t it nice?',
    'œuvre',
]


def corrupt(s: str) -> str:
    return s.encode('utf-8').decode('latin-1')


@pytest.mark.parametrize('original', CLEAN)
def test_fix_restores_single_corruption(original):
    assert fix(corrupt(original)) == original


@pytest.mark.parametrize('original', CLEAN)
def test_fix_on_clean_text_is_noop(original):
    assert fix(original) == original


@pytest.mark.parametrize('original', CLEAN)
def test_double_corruption_restored_by_applying_fix_twice(original):
    twice = corrupt(corrupt(original))
    assert fix(fix(twice)) == original


@pytest.mark.parametrize('original', CLEAN)
def test_idempotent_once_clean(original):
    once = fix(fix(original))
    assert fix(once) == once == original


def test_detect_confidence_bounds_and_ordering():
    for original in CLEAN:
        bad = corrupt(original)
        assert 0.0 <= detect(original) <= 1.0
        assert 0.0 <= detect(bad) <= 1.0
    assert detect(corrupt('café naïve')) > detect('café naïve')
    assert detect('') == 0.0


def test_detect_positive_on_signature_strings():
    assert detect('cafÃ©') > 0
    assert detect('â€™ â€œ') > 0

