"""Detect and repair classic UTF-8-read-as-Latin-1 mojibake (e.g. 'café' -> 'cafÃ©')."""

import re

# Signature characters that dominate UTF-8-as-Latin-1 artifacts
# ('Ã©', 'â€™', 'â€œ', 'Ã¼', ...). 'Â' is included because it appears in
# doubly-corrupted text ('Ã‚Â©') and is needed to peel one layer at a time.
SUSPICIOUS = frozenset({'Ã', 'â', '€', '™', 'œ', '¢', 'å', 'Â'})


def _suspicious_count(s: str) -> int:
    return sum(1 for ch in s if ch in SUSPICIOUS)


def _has_suspicious_pair(word: str) -> bool:
    """A word is flagged if it contains two adjacent chars where both are
    suspicious or non-ASCII (the classic 'Ã©'-style pairing)."""
    def marker(ch: str) -> bool:
        return ch in SUSPICIOUS or ord(ch) > 127

    return any(marker(a) and marker(b) for a, b in zip(word, word[1:]))


def fix(s: str) -> str:
    """Repair mojibake by re-encoding Latin-1 -> decoding UTF-8, but only when
    it strictly reduces the suspicious-character count; otherwise return s."""
    try:
        candidate = s.encode('latin-1').decode('utf-8')
    except (UnicodeEncodeError, UnicodeDecodeError):
        return s
    if _suspicious_count(candidate) < _suspicious_count(s):
        return candidate
    return s


def detect(s: str) -> float:
    """Confidence in [0, 1]: fraction of words containing a suspicious pair."""
    words = re.findall(r'\S+', s)
    if not words:
        return 0.0
    return sum(_has_suspicious_pair(w) for w in words) / len(words)

