"""Detect and repair classic UTF-8-read-as-Latin-1 mojibake (e.g. 'café' -> 'cafÃ©')."""

import re

# Signature characters that dominate UTF-8-as-Latin-1 artifacts
# ('Ã©', 'â€™', 'â€œ', 'Ã¼', ...).
SUSPICIOUS = frozenset({'Ã', 'â', '€', '™', 'œ', '¢', 'å'})


def _marker(ch: str) -> bool:
    """True if ch participates in mojibake signatures (suspicious char or any
    leftover non-ASCII byte char from Latin-1 decoding)."""
    return ch in SUSPICIOUS or ord(ch) > 127


def _has_pair(text: str) -> bool:
    """Classic signature: two adjacent chars that both look like mojibake."""
    return any(_marker(a) and _marker(b) for a, b in zip(text, text[1:]))


def _pair_count(s: str) -> int:
    """Number of adjacent suspicious/non-ASCII pairs — the mojibake signal.
    Used instead of raw character counts so legitimate accents ('œuvre',
    'é') don't mask or fake reductions."""
    return sum(1 for a, b in zip(s, s[1:]) if _marker(a) and _marker(b))


def fix(s: str) -> str:
    """Repair mojibake by re-encoding Latin-1 -> decoding UTF-8, but only when
    the result strictly reduces the mojibake signal; otherwise return s."""
    try:
        candidate = s.encode('latin-1').decode('utf-8')
    except (UnicodeEncodeError, UnicodeDecodeError):
        return s
    if _pair_count(candidate) < _pair_count(s):
        return candidate
    return s


def detect(s: str) -> float:
    """Confidence in [0, 1]: fraction of words containing a suspicious pair."""
    words = re.findall(r'\S+', s)
    if not words:
        return 0.0
    return sum(1 for w in words if _has_pair(w)) / len(words)

